        pub struct ResponseError {
            pub result: crate::types::common::OperationResult,
            pub extended_error_code: Option<u16>,
        }
        impl ResponseError {
            pub fn from_tlvs(tlvs: &[TlvBuf]) -> Result<Self, Error> {
                let result = crate::result::decode_result(tlvs)?;
                let mut out = Self {
                    result,
                    ..Default::default()
                };
                {
                    let out = &mut out;
                    if out.result.error_code == 81 {
                        if let Some(tlv) = tlvs.iter().find(|tlv| tlv.id == 224) {
                            let mut reader = TlvReader::new(&tlv.value);
                            let value = reader.read_u16(Endian::Little)?;
                            out.extended_error_code = Some(value);
                        }
                    }
                }
                Ok(out)
            }
            pub fn to_tlvs(&self) -> Result<Vec<TlvBuf>, Error> {
                let mut result = TlvWriter::new();
                self.result.encode_to(&mut result)?;
                let mut tlvs = alloc::vec![result.into_tlv(crate::TLV_RESULT)];
                if let Some(value) = &self.extended_error_code {
                    let mut writer = TlvWriter::new();
                    writer.write_u16(*value, Endian::Little);
                    tlvs.push(writer.into_tlv(224));
                }
                Ok(tlvs)
            }
        }
