                writer.write_u32(*&self.max_uplink_bitrate, Endian::Little);
                writer.write_u32(*&self.max_downlink_bitrate, Endian::Little);
                writer.write_u32(*&self.guaranteed_uplink_bitrate, Endian::Little);
                writer.write_u32(*&self.guaranteed_downlink_bitrate, Endian::Little);
