                writer.write_u8(*&self.residual_bit_error_ratio);
                writer.write_u8(*&self.delivery_erroneous_sdu);
                writer.write_u32(*&self.transfer_delay, Endian::Little);
                writer.write_u32(*&self.traffic_handling_priority, Endian::Little);
                Ok(())
