                out.max_downlink_bitrate = reader.read_u32(Endian::Little)?;
                out.guaranteed_uplink_bitrate = reader.read_u32(Endian::Little)?;
                out.guaranteed_downlink_bitrate = reader.read_u32(Endian::Little)?;
                out.qos_delivery_order = reader.read_u8()?;
