        pub struct Ipv6AddressPreference {
            pub address: Vec<u16>,
        }
        impl Ipv6AddressPreference {
            pub fn encode_to(&self, writer: &mut TlvWriter) -> Result<(), Error> {
                if (&self.address).len() != 8 {
                    return Err(Error::InvalidLength);
                }
                for item in &self.address {
                    writer.write_u16(*item, Endian::Big);
                }
                Ok(())
            }
            pub fn decode_from(reader: &mut TlvReader<'_>) -> Result<Self, Error> {
                let mut out = Self::default();
                let count = 8;
                let mut items = Vec::with_capacity(count.min(256));
                for _ in 0..count {
                    items.push(reader.read_u16(Endian::Big)?);
                }
                out.address = items;
                Ok(out)
            }
        }
